import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.ChIlRNAd.js";const h=JSON.parse('{"title":"Jobs & Queue (BullMQ)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/technical/jobs.md","filePath":"fr/technical/jobs.md"}'),o={name:"fr/technical/jobs.md"};function i(n,e,r,c,l,u){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="jobs-queue-bullmq" tabindex="-1">Jobs &amp; Queue (BullMQ) <a class="header-anchor" href="#jobs-queue-bullmq" aria-label="Permalink to &quot;Jobs &amp; Queue (BullMQ)&quot;">​</a></h1><h2 id="pourquoi-bullmq" tabindex="-1">Pourquoi BullMQ <a class="header-anchor" href="#pourquoi-bullmq" aria-label="Permalink to &quot;Pourquoi BullMQ&quot;">​</a></h2><p>Les opérations sur Gmail (action de masse, archivage de milliers de mails) peuvent prendre plusieurs minutes. Une requête HTTP synchrone timeouterait inévitablement.</p><p>BullMQ permet :</p><ul><li>Enqueue du job → réponse <code>202 Accepted</code> immédiate avec un <code>jobId</code></li><li>Exécution asynchrone dans un worker</li><li>Suivi de la progression en SSE</li><li>Retry automatique en cas d&#39;erreur (backoff exponentiel, 3 tentatives)</li><li>Annulation d&#39;un job tant qu&#39;il n&#39;a pas démarré</li></ul><hr><h2 id="types-de-jobs" tabindex="-1">Types de jobs <a class="header-anchor" href="#types-de-jobs" aria-label="Permalink to &quot;Types de jobs&quot;">​</a></h2><p><code>JobType</code> (<code>backend/src/jobs/queue.ts</code>). Tous les types sont traités par le <strong>worker unifié</strong> (<code>jobs/workers/unified.worker.ts</code>), qui dispatche par <code>job.name</code> :</p><table tabindex="0"><thead><tr><th>Type</th><th>Enfilé par</th></tr></thead><tbody><tr><td><code>bulk_operation</code></td><td><code>POST /api/gmail/:accountId/messages/bulk</code> (ids ou requête Gmail) ; <code>POST /api/unsubscribe/:accountId/newsletters/:senderEmail/delete</code> ; <code>runRule()</code> pour les actions Gmail</td></tr><tr><td><code>archive_mails</code></td><td><code>POST /api/archive/:accountId/archive</code> ; <code>runRule()</code> pour l&#39;action <code>archive_nas</code> ; scheduler (sauvegarde NAS automatique) ; le worker lui-même (suite d&#39;une sauvegarde plafonnée)</td></tr><tr><td><code>run_rule</code></td><td><code>POST /api/rules/:accountId/:ruleId/run</code> ; scheduler (règles planifiées)</td></tr><tr><td><code>scan_unsubscribe</code></td><td><code>POST /api/unsubscribe/:accountId/scan</code></td></tr><tr><td><code>integrity_check</code></td><td><code>POST /api/integrity/check/async</code> (admin) ; scheduler (quotidien, 3 h)</td></tr><tr><td><code>encrypt_archives</code></td><td><code>POST /api/privacy/:accountId/encryption/encrypt</code></td></tr><tr><td><code>import_mbox</code></td><td><code>POST /api/import/:accountId/mbox</code></td></tr><tr><td><code>import_imap</code></td><td><code>POST /api/import/:accountId/imap</code></td></tr><tr><td><code>restore_gmail</code></td><td><code>POST /api/archive/:accountId/mails/restore-mailbox</code> (compte Gmail)</td></tr><tr><td><code>restore_imap</code></td><td><code>POST /api/archive/:accountId/mails/restore-mailbox</code> (compte IMAP) ; un mot de passe refusé passe le compte « à reconnecter »</td></tr><tr><td><code>purge_archive_trash</code></td><td>scheduler (quotidien, 4 h)</td></tr><tr><td><code>backfill_body_text</code></td><td>scheduler, une fois au démarrage s&#39;il reste des archives sans <code>body_text</code> ou des PJ PDF/DOCX sans <code>text_content</code> (corps puis PJ)</td></tr><tr><td><code>apply_retention</code></td><td>Aucun appelant actuellement : <code>POST /api/retention/run</code> applique les politiques de façon synchrone</td></tr></tbody></table><p><code>POST /api/jobs/:jobId/retry</code> peut ré-enfiler n&#39;importe quel type (voir <a href="#relance">Relance</a>).</p><hr><h2 id="configuration-de-la-queue" tabindex="-1">Configuration de la queue <a class="header-anchor" href="#configuration-de-la-queue" aria-label="Permalink to &quot;Configuration de la queue&quot;">​</a></h2><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Queue partagée &quot;nid&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defaultJobOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  attempts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 3 tentatives en cas d&#39;échec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  backoff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;exponential&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2s, 4s, 8s</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  removeOnComplete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Garder les 100 derniers jobs complétés</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  removeOnFail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Garder les 50 derniers jobs en erreur</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>enqueueJob(type, payload, opts)</code> accepte deux options :</p><ul><li><code>dedupId</code> : tant qu&#39;un job avec cet id attend ou tourne, un nouvel enqueue est ignoré (règles planifiées, sauvegardes, backfill).</li><li><code>delay</code> (ms) : le job reste <code>scheduled</code> (BullMQ <code>delayed</code>) jusque-là et peut encore être annulé.</li></ul><p>Les identifiants sensibles du payload (<code>passphrase</code>, <code>imapConfig.pass</code>) sont retirés de la copie stockée en base ; dans Redis, ces jobs sont supprimés dès leur fin.</p><hr><h2 id="concurrence" tabindex="-1">Concurrence <a class="header-anchor" href="#concurrence" aria-label="Permalink to &quot;Concurrence&quot;">​</a></h2><p>Le worker unifié a une concurrence de <strong>3</strong> (3 jobs simultanés max), partagée par tous les types. Les appels Gmail sont en plus limités par compte (<code>gmail/gmail-throttle.ts</code>).</p><hr><h2 id="tracking-en-base-de-donnees" tabindex="-1">Tracking en base de données <a class="header-anchor" href="#tracking-en-base-de-donnees" aria-label="Permalink to &quot;Tracking en base de données&quot;">​</a></h2><p>Chaque job est tracké dans la table <code>jobs</code> (PostgreSQL) pour :</p><ul><li>Persistance après redémarrage (BullMQ Redis peut être vidé)</li><li>Accès à l&#39;historique même après <code>removeOnComplete</code></li><li>Affichage dans le frontend sans dépendance directe à Redis</li></ul><h3 id="pre-insertion" tabindex="-1">Pré-insertion <a class="header-anchor" href="#pre-insertion" aria-label="Permalink to &quot;Pré-insertion&quot;">​</a></h3><p><code>enqueueJob()</code> insère immédiatement une ligne dans <code>jobs</code> (<code>status: &#39;pending&#39;</code>, ou <code>&#39;scheduled&#39;</code> avec <code>delay</code>), sauf si BullMQ a dédupliqué le job. Le frontend (SSE) trouve donc le job sans délai.</p><p>Les handlers font ensuite un <code>UPDATE</code> (et non un <code>INSERT</code>) pour passer le job en <code>active</code>, puis <code>completed</code> ou <code>failed</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pending   → active → completed</span></span>
<span class="line"><span>scheduled ↗        → failed</span></span>
<span class="line"><span>pending / scheduled → cancelled (annulation manuelle ; 409 une fois active)</span></span></code></pre></div><p><code>GET /api/jobs</code> liste les jobs de l&#39;utilisateur sur 30 jours (filtres <code>status</code> en liste séparée par des virgules, <code>accountId</code>, <code>limit</code> ; <code>withCounts=true</code> ajoute le décompte par statut pour la page Activité).</p><hr><h2 id="fenetre-d-annulation" tabindex="-1">Fenêtre d&#39;annulation <a class="header-anchor" href="#fenetre-d-annulation" aria-label="Permalink to &quot;Fenêtre d&#39;annulation&quot;">​</a></h2><p>Les actions destructrices sont enfilées avec <code>delay = delayMs</code> (corps de requête, <strong>10 s par défaut</strong>, 0 à 60 s) :</p><ul><li><code>POST /api/gmail/:accountId/messages/bulk</code></li><li><code>POST /api/unsubscribe/:accountId/newsletters/:senderEmail/delete</code></li><li><code>POST /api/rules/:accountId/:ruleId/run</code></li></ul><p>La réponse contient le <code>jobId</code> BullMQ et <code>runAt</code>. Pendant ce délai, <code>DELETE /api/jobs/:jobId</code> (id BullMQ ou id de ligne) retire le job de la queue et passe la ligne en <code>cancelled</code>. Un job déjà <code>active</code> ne peut pas être arrêté : la route répond <strong>409</strong>. Côté frontend, <code>UndoToast</code> affiche le compte à rebours.</p><hr><h2 id="relance" tabindex="-1">Relance <a class="header-anchor" href="#relance" aria-label="Permalink to &quot;Relance&quot;">​</a></h2><p><code>POST /api/jobs/:jobId/retry</code> ré-enfile le payload stocké sous un nouvel id (<code>retryOf</code> = id de la ligne d&#39;origine) et répond <code>202 { jobId, retryOf }</code>. Les types dont les identifiants ne sont pas stockés (<code>import_imap</code>, <code>encrypt_archives</code>) sont refusés en <strong>409</strong> : il faut les relancer depuis leur page.</p><p>Les actions de masse plafonnées (<code>BULK_QUERY_MAX</code>, 50 000 par défaut) ne se relancent pas seules : une notification propose de relancer. Les sauvegardes NAS plafonnées enchaînent en revanche une suite différentielle après <code>ARCHIVE_CONTINUE_DELAY_MIN</code> minutes (15 par défaut), au plus <code>ARCHIVE_CHAIN_MAX</code> fois (20).</p><hr><h2 id="suivi-temps-reel-sse" tabindex="-1">Suivi temps réel (SSE) <a class="header-anchor" href="#suivi-temps-reel-sse" aria-label="Permalink to &quot;Suivi temps réel (SSE)&quot;">​</a></h2><h3 id="par-job-get-api-jobs-jobid-events" tabindex="-1">Par job : <code>GET /api/jobs/:jobId/events</code> <a class="header-anchor" href="#par-job-get-api-jobs-jobid-events" aria-label="Permalink to &quot;Par job : \`GET /api/jobs/:jobId/events\`&quot;">​</a></h3><ul><li><code>:jobId</code> = id BullMQ ou id de ligne ; le job doit appartenir à l&#39;utilisateur (sinon 404)</li><li>Envoie l&#39;état courant de la ligne <code>jobs</code> à la connexion ; si le job est déjà terminé, envoie l&#39;état final puis <code>event: close</code></li><li>Le broadcaster (<code>startQueueEventBroadcaster</code>) écoute les <code>QueueEvents</code> BullMQ (<code>progress</code>, <code>completed</code>, <code>failed</code>) et relit la ligne <code>jobs</code> (par <code>bullmq_id</code>) avant de diffuser <code>{ status, progress, processed, total }</code></li><li>Heartbeat toutes les 15 s</li><li>Côté frontend : <code>useJobSSE(jobId)</code> (reconnexion avec backoff), affiché par <code>JobProgressInline</code></li></ul><h3 id="par-utilisateur-get-api-events" tabindex="-1">Par utilisateur : <code>GET /api/events</code> <a class="header-anchor" href="#par-utilisateur-get-api-events" aria-label="Permalink to &quot;Par utilisateur : \`GET /api/events\`&quot;">​</a></h3><p>Flux de l&#39;utilisateur connecté, via un canal Redis pub/sub par utilisateur (<code>events/events.service.ts</code>) :</p><ul><li><code>counters</code> à la connexion et à chaque changement : <code>{ mails, activeRules, activeJobs }</code></li><li><code>job</code> quand un job démarre ou se termine (publié par le worker)</li><li>Heartbeat toutes les 30 s</li><li>Côté frontend : <code>useLiveCounters()</code> (badges de navigation)</li></ul><p>Les toasts de fin de job viennent de <code>useGlobalJobNotifier</code> (poll des jobs actifs toutes les 5 s) et les notifications in-app de <code>notify()</code> côté worker.</p><hr><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><p><code>startRuleScheduler()</code> (<code>jobs/scheduler.ts</code>) tourne toutes les <strong>60 secondes</strong> dans le processus API :</p><table tabindex="0"><thead><tr><th>Tâche</th><th>Fréquence</th><th>Mode</th></tr></thead><tbody><tr><td><code>integrity_check</code></td><td>Quotidien (tick de 3 h)</td><td>Job</td></tr><tr><td><code>purge_archive_trash</code></td><td>Quotidien (tick de 4 h)</td><td>Job</td></tr><tr><td>Sauvegarde NAS automatique (<code>archive_mails</code> différentiel)</td><td>Selon <code>mail_accounts.backup_interval</code> (1h / 6h / 24h), comptes actifs avec <code>backup_enabled</code> et sans <code>auth_error_at</code></td><td>Job, <code>dedupId: backup-&lt;accountId&gt;</code></td></tr><tr><td>Règles planifiées (<code>run_rule</code>)</td><td><code>hourly</code>, <code>daily</code>, <code>weekly</code>, <code>monthly</code> selon <code>rules.last_run_at</code></td><td>Job, <code>dedupId: run_rule-&lt;ruleId&gt;</code></td></tr><tr><td><code>backfill_body_text</code></td><td>Une fois au démarrage, s&#39;il reste des archives à remplir</td><td>Job</td></tr><tr><td>Snapshots Inbox Zero</td><td>Toutes les 6 h</td><td>Dans le processus</td></tr><tr><td>Synchro des libellés Gmail (<code>syncAllLabels()</code>)</td><td>Quotidien (premier tick après le démarrage)</td><td>Dans le processus — voir <a href="./api/labels.html">API — Libellés</a></td></tr><tr><td>Mails expirés (<code>processExpiredEmails()</code>)</td><td>Toutes les 15 min</td><td>Dans le processus</td></tr><tr><td>Liens de partage expirés (<code>cleanupExpiredShares()</code>)</td><td>Toutes les heures</td><td>Dans le processus</td></tr></tbody></table><p><code>startReportScheduler()</code> (<code>reports/report.scheduler.ts</code>) vérifie toutes les heures et génère, le lundi, le rapport hebdomadaire de chaque utilisateur sous forme de notification.</p><h3 id="purge-de-la-corbeille-archives" tabindex="-1">Purge de la corbeille archives <a class="header-anchor" href="#purge-de-la-corbeille-archives" aria-label="Permalink to &quot;Purge de la corbeille archives&quot;">​</a></h3><p>Le job <code>purge_archive_trash</code> :</p><ol><li>Lit la configuration depuis la table <code>system_config</code> (<code>archive_trash_retention_days</code>, <code>archive_trash_purge_enabled</code>)</li><li>Si désactivé (<code>purge_enabled = false</code>), le job se termine sans action</li><li>Recherche les mails archivés dont <code>deleted_at &lt; maintenant - retention_days</code></li><li>Supprime les fichiers associés (EML + pièces jointes) du stockage</li><li>Supprime les entrées en base de données</li></ol><p>La rétention par défaut est de <strong>30 jours</strong>. Elle est configurable par un admin (<code>PUT /api/archive/config/trash</code>) ou directement dans la table <code>system_config</code>.</p>`,54)])])}const b=t(o,[["render",i]]);export{h as __pageData,b as default};
